using System;

public class Person {
    public string Name { get; set; }
}

public class C {
    public void M(Person p) {
        switch (p) {
            case { Name: "Bill" }:
                Console.WriteLine("Hey Bill!");
            break;
            case { Name: "Bob" }:
                Console.WriteLine("Hey Bob!");
            break;
            case { Name: var name }:
                Console.WriteLine($"Hello {name}!");
            break;
        }
    }
}
